{
  "name": "CustomerInfo",
  "type": "object",
  "properties": {
    "designer": {
      "type": "string",
      "description": "Designer assigned"
    },
    "surveyor": {
      "type": "string",
      "description": "Surveyor assigned"
    },
    "initial_contact_date": {
      "type": "string",
      "format": "date",
      "description": "Date of initial contact"
    },
    "site_survey_date": {
      "type": "string",
      "format": "date",
      "description": "Site survey date"
    },
    "site_survey_time": {
      "type": "string",
      "description": "Site survey time"
    },
    "site_survey_am_pm": {
      "type": "string",
      "enum": [
        "AM",
        "PM"
      ],
      "description": "AM or PM for site survey"
    },
    "customer_name": {
      "type": "string",
      "description": "Customer name"
    },
    "representative": {
      "type": "string",
      "description": "Customer representative"
    },
    "address": {
      "type": "string",
      "description": "Customer address"
    },
    "address_line_2": {
      "type": "string",
      "description": "Address line 2"
    },
    "contact_phone": {
      "type": "string",
      "description": "Contact phone number"
    },
    "email": {
      "type": "string",
      "description": "Customer email"
    },
    "billing_address": {
      "type": "string",
      "description": "Billing address"
    },
    "billing_address_line_2": {
      "type": "string",
      "description": "Billing address line 2"
    },
    "additional_contact": {
      "type": "string",
      "description": "Additional contact person"
    },
    "permitting": {
      "type": "string",
      "enum": [
        "yes",
        "no",
        "maybe",
        "na"
      ],
      "description": "Permitting required"
    },
    "township_city": {
      "type": "string",
      "description": "Township or City"
    },
    "county": {
      "type": "string",
      "description": "County"
    },
    "code": {
      "type": "string",
      "description": "Permit code"
    },
    "class": {
      "type": "string",
      "description": "Permit class"
    },
    "owner": {
      "type": "string",
      "description": "Property owner"
    },
    "pud": {
      "type": "string",
      "description": "PUD"
    },
    "parcel_number": {
      "type": "string",
      "description": "Parcel number"
    },
    "electrical_ibi": {
      "type": "boolean",
      "default": false,
      "description": "IBI electrical"
    },
    "electrical_nkyei": {
      "type": "boolean",
      "default": false,
      "description": "NKYEI electrical"
    },
    "electrical_nec": {
      "type": "boolean",
      "default": false,
      "description": "NEC electrical"
    },
    "electrical_city": {
      "type": "boolean",
      "default": false,
      "description": "City electrical"
    },
    "electrical_county": {
      "type": "boolean",
      "default": false,
      "description": "County electrical"
    },
    "customer_is_building_owner": {
      "type": "boolean",
      "default": false,
      "description": "Customer is building owner"
    },
    "customer_is_tenant": {
      "type": "boolean",
      "default": false,
      "description": "Customer is tenant"
    },
    "customer_is_marketing_co": {
      "type": "boolean",
      "default": false,
      "description": "Customer is marketing company"
    },
    "business_co_coo_reminder": {
      "type": "boolean",
      "default": false,
      "description": "Business CO or COO reminder"
    },
    "business_co_coo_date": {
      "type": "string",
      "description": "CO/COO reminder date"
    },
    "install_yes": {
      "type": "boolean",
      "default": false,
      "description": "Install yes"
    },
    "install_no": {
      "type": "boolean",
      "default": false,
      "description": "Install no"
    },
    "install_due_date": {
      "type": "string",
      "format": "date",
      "description": "Install due date"
    },
    "budget_less_than": {
      "type": "number",
      "description": "Budget less than amount"
    },
    "removal_yes": {
      "type": "boolean",
      "default": false,
      "description": "Removal yes"
    },
    "removal_no": {
      "type": "boolean",
      "default": false,
      "description": "Removal no"
    },
    "service_repair": {
      "type": "string",
      "description": "Service/Repair description"
    },
    "origination": {
      "type": "string",
      "description": "Lead origination source"
    },
    "patch": {
      "type": "string",
      "description": "Patch details"
    },
    "paint": {
      "type": "string",
      "description": "Paint details"
    },
    "color": {
      "type": "string",
      "description": "Color specification"
    },
    "product_1": {
      "type": "string",
      "description": "Product #1"
    },
    "product_2": {
      "type": "string",
      "description": "Product #2"
    },
    "product_3": {
      "type": "string",
      "description": "Product #3"
    },
    "product_4": {
      "type": "string",
      "description": "Product #4"
    },
    "product_5": {
      "type": "string",
      "description": "Product #5"
    },
    "product_6": {
      "type": "string",
      "description": "Product #6"
    },
    "cb_complete": {
      "type": "boolean",
      "default": false,
      "description": "CB complete"
    },
    "cf_complete": {
      "type": "boolean",
      "default": false,
      "description": "CF complete"
    },
    "cc_complete": {
      "type": "boolean",
      "default": false,
      "description": "CC complete"
    },
    "sms_complete": {
      "type": "boolean",
      "default": false,
      "description": "SMS complete"
    },
    "notes": {
      "type": "array",
      "description": "Notes with timestamps and completion status",
      "items": {
        "type": "object",
        "properties": {
          "text": {
            "type": "string"
          },
          "timestamp": {
            "type": "string",
            "format": "date-time"
          },
          "created_by": {
            "type": "string"
          },
          "completed": {
            "type": "boolean",
            "default": false
          },
          "sub_tasks": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "text": {
                  "type": "string"
                },
                "completed": {
                  "type": "boolean",
                  "default": false
                }
              }
            }
          }
        }
      }
    },
    "follow_up": {
      "type": "array",
      "description": "Follow up items",
      "items": {
        "type": "object",
        "properties": {
          "text": {
            "type": "string"
          },
          "timestamp": {
            "type": "string",
            "format": "date-time"
          },
          "created_by": {
            "type": "string"
          },
          "completed": {
            "type": "boolean",
            "default": false
          }
        }
      }
    },
    "status": {
      "type": "string",
      "enum": [
        "active",
        "completed",
        "on_hold",
        "cancelled"
      ],
      "default": "active",
      "description": "Form status"
    },
    "linked_work_order_id": {
      "type": "string",
      "description": "Linked work order ID"
    }
  },
  "required": [
    "customer_name"
  ],
  "rls": {
    "create": { "user_condition": { "role": "__customerinfo_backend_only__" } },
    "read": { "user_condition": { "role": "__customerinfo_backend_only__" } },
    "update": { "user_condition": { "role": "__customerinfo_backend_only__" } },
    "delete": { "user_condition": { "role": "__customerinfo_backend_only__" } }
  }
}

{
  "name": "CustomerLocation",
  "type": "object",
  "description": "Canonical reusable physical location/site belonging to a shared Customer. Owns site identity, addressing and jurisdiction hints. Opportunity, EstimatingRequest, Orders and future installation/permitting flows link here by location_id once resolved.",
  "properties": {
    "schema_version": {
      "type": "number",
      "default": 1
    },
    "creation_request_key": {
      "type": "string",
      "description": "Stable retry-safe receipt for one location create."
    },
    "customer_id": {
      "type": "string",
      "description": "Owning canonical Customer id."
    },
    "label": {
      "type": "string",
      "description": "Human label such as 'Main Office', 'Storefront', or the street address."
    },
    "address_line_1": {
      "type": "string"
    },
    "address_line_2": {
      "type": "string"
    },
    "city": {
      "type": "string"
    },
    "state": {
      "type": "string"
    },
    "postal_code": {
      "type": "string"
    },
    "country": {
      "type": "string",
      "default": "US"
    },
    "site_type": {
      "type": "string",
      "enum": [
        "unknown",
        "install",
        "billing",
        "install_and_billing",
        "mailing",
        "other"
      ],
      "default": "unknown"
    },
    "is_primary_site": {
      "type": "boolean",
      "default": false
    },
    "is_billing_address": {
      "type": "boolean",
      "default": false
    },
    "jurisdiction_profile_id": {
      "type": "string",
      "description": "Resolved Permitting JurisdictionProfile id when known. Nullable until jurisdiction resolution runs; never fabricate."
    },
    "jurisdiction_name": {
      "type": "string",
      "description": "Display jurisdiction name captured with the resolution evidence."
    },
    "county": {
      "type": "string"
    },
    "parcel_id": {
      "type": "string"
    },
    "property_owner_name": {
      "type": "string",
      "description": "Property owner of record when different from the customer; permitting evidence."
    },
    "access_notes": {
      "type": "string",
      "description": "Gate codes, entry instructions, site contact details."
    },
    "source_summary": {
      "type": "object",
      "additionalProperties": true,
      "description": "Provenance: which record/import promoted this location (e.g. WorkOrder install_location, Customer billing address, OpportunityIntake capture)."
    },
    "notes": {
      "type": "string"
    },
    "is_active": {
      "type": "boolean",
      "default": true
    }
  },
  "required": [
    "customer_id"
  ],
  "rls": {
    "create": { "user_condition": { "role": "__customerlocation_backend_only__" } },
    "read": { "user_condition": { "role": "__customerlocation_backend_only__" } },
    "update": { "user_condition": { "role": "__customerlocation_backend_only__" } },
    "delete": { "user_condition": { "role": "__customerlocation_backend_only__" } }
  }
}

{
  "name": "CustomerNote",
  "type": "object",
  "description": "A note or a flag attached to a Customer. Notes are internal history entries; flags are short warnings shown on the customer header and on estimates for that customer (e.g. 'Credit hold', 'Prepay only').",
  "properties": {
    "customer_id": {
      "type": "string"
    },
    "kind": {
      "type": "string",
      "enum": [
        "note",
        "flag"
      ],
      "default": "note"
    },
    "text": {
      "type": "string"
    },
    "flag_color": {
      "type": "string",
      "enum": [
        "red",
        "amber",
        "blue",
        "green"
      ],
      "default": "amber",
      "description": "Badge color used when kind = flag."
    }
  },
  "required": [
    "customer_id",
    "text"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__customer_note_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__customer_note_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__customer_note_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__customer_note_backend_only__"
      }
    }
  }
}

{
  "name": "CustomerPortalLink",
  "type": "object",
  "description": "Bearer-token share link for the customer portal. The token itself is the capability \u2014 whoever holds it can read the linked record's sanitized view. Backend-only; created/revoked by staff through customerPortalAction.",
  "properties": {
    "schema_version": {
      "type": "number",
      "default": 1
    },
    "creation_request_key": {
      "type": "string",
      "description": "Stable retry-safe receipt for one portal link."
    },
    "token": {
      "type": "string",
      "description": "Random bearer token embedded in the share URL."
    },
    "kind": {
      "type": "string",
      "enum": [
        "invoice",
        "customer"
      ]
    },
    "record_id": {
      "type": "string"
    },
    "customer_id": {
      "type": "string"
    },
    "label": {
      "type": "string"
    },
    "created_by": {
      "type": "string"
    },
    "expires_at": {
      "type": "string",
      "format": "date-time"
    },
    "revoked": {
      "type": "boolean",
      "default": false
    },
    "revoked_at": {
      "type": "string",
      "format": "date-time"
    },
    "last_opened_at": {
      "type": "string",
      "format": "date-time"
    },
    "open_count": {
      "type": "number",
      "default": 0
    }
  },
  "required": [
    "creation_request_key",
    "token",
    "kind",
    "record_id"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__portal_link_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__portal_link_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__portal_link_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__portal_link_backend_only__"
      }
    }
  }
}

{
  "name": "CustomerSummary",
  "type": "object",
  "description": "A saved multi-module summary for a client, bundling projects from different estimator modules under one tier.",
  "properties": {
    "summary_name": {
      "type": "string"
    },
    "client_name": {
      "type": "string"
    },
    "summary_key": {
      "type": "string",
      "description": "Internal deterministic key used only for concurrency-safe Customer Summary creation. Historical summary rows are not required to have it."
    },
    "customer_id": {
      "type": "string",
      "description": "Linked shared Customer record id."
    },
    "estimate_number": {
      "type": "string"
    },
    "tier_number": {
      "type": "number",
      "default": 1,
      "description": "Selected pricing tier 1-8."
    },
    "linked_projects": {
      "type": "array",
      "description": "List of projects from different modules included in this summary.",
      "items": {
        "type": "object",
        "properties": {
          "module": {
            "type": "string",
            "enum": [
              "channel_letter_installation",
              "foundation",
              "brick_stone",
              "paint",
              "laser",
              "cnc",
              "metal_fabrication",
              "vinyl",
              "sign_maintenance"
            ]
          },
          "project_id": {
            "type": "string"
          },
          "project_name": {
            "type": "string"
          }
        }
      }
    },
    "notes": {
      "type": "string"
    }
  },
  "required": [
    "summary_name"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__admin_settings_backend_only__"
      }
    },
    "read": {
      "$or": [
        {
          "created_by_id": "{{user.id}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        }
      ]
    },
    "update": {
      "$or": [
        {
          "created_by_id": "{{user.id}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        }
      ]
    },
    "delete": {
      "$or": [
        {
          "created_by_id": "{{user.id}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        }
      ]
    }
  }
}

{
  "name": "DO_NOT_USE",
  "type": "object",
  "description": "Disabled empty schema created accidentally during MCP tool switching. Contains no records and is intentionally inaccessible pending removal through a Base44 schema-delete surface.",
  "properties": {},
  "required": [],
  "rls": {
    "create": { "user_condition": { "role": "__do_not_use_backend_only__" } },
    "read": { "user_condition": { "role": "__do_not_use_backend_only__" } },
    "update": { "user_condition": { "role": "__do_not_use_backend_only__" } },
    "delete": { "user_condition": { "role": "__do_not_use_backend_only__" } }
  }
}

{
  "name": "DefaultModuleSettings",
  "type": "object",
  "properties": {
    "module_name": {
      "type": "string",
      "enum": [
        "painting",
        "laser",
        "cnc",
        "metal_fabrication",
        "channel_letter_installation",
        "foundation",
        "brick_stone",
        "sign_maintenance",
        "vinyl_estimator"
      ],
      "description": "The unique identifier for the module."
    },
    "is_enabled": {
      "type": "boolean",
      "default": true,
      "description": "The default enabled state for new users."
    }
  },
  "required": [
    "module_name",
    "is_enabled"
  ],
  "rls": {
    "create": { "user_condition": { "role": "__defaultmodulesettings_backend_only__" } },
    "read": { "user_condition": { "role": "__defaultmodulesettings_backend_only__" } },
    "update": { "user_condition": { "role": "__defaultmodulesettings_backend_only__" } },
    "delete": { "user_condition": { "role": "__defaultmodulesettings_backend_only__" } }
  }
}

{
  "name": "DimensionalLetterMaterial",
  "type": "object",
  "description": "Sheet-goods catalog for dimensional letters, lobby sign backers, and sign-maintenance face/return/vinyl replacement material pickers.",
  "properties": {
    "material_name": {
      "type": "string",
      "description": "Friendly name shown in dropdowns (e.g., '1/2\" PVC Sintra White')"
    },
    "material_type": {
      "type": "string",
      "enum": [
        "acrylic",
        "pvc",
        "aluminum_composite",
        "aluminum_solid",
        "aluminum_sheet",
        "steel_sheet",
        "stainless_sheet",
        "galvanized_sheet",
        "polycarbonate",
        "styrene",
        "coroplast",
        "gatorboard",
        "wood",
        "mdf",
        "hdu",
        "foam",
        "other"
      ],
      "default": "pvc"
    },
    "thickness_inches": {
      "type": "number",
      "default": 0.5,
      "description": "Sheet thickness in inches"
    },
    "sheet_length_inches": {
      "type": "number",
      "default": 96,
      "description": "Sheet length (e.g., 96 for 4x8)"
    },
    "sheet_width_inches": {
      "type": "number",
      "default": 48,
      "description": "Sheet width (e.g., 48 for 4x8)"
    },
    "cost_per_sheet": {
      "type": "number",
      "default": 0,
      "description": "Cost for one full sheet at the listed dimensions"
    },
    "yield_factor": {
      "type": "number",
      "default": 0.7,
      "description": "Estimated usable yield after nesting waste (0.5 = 50% usable)."
    },
    "color": {
      "type": "string",
      "description": "Stock color, if applicable"
    },
    "supplier": {
      "type": "string"
    },
    "needs_painting": {
      "type": "boolean",
      "default": true,
      "description": "If false, default to skipping paint cost"
    },
    "allow_laser": {
      "type": "boolean",
      "default": true,
      "description": "Whether this material can be cut on the laser"
    },
    "notes": {
      "type": "string"
    },
    "is_active": {
      "type": "boolean",
      "default": true
    },
    "sort_order": {
      "type": "number",
      "default": 0
    },
    "show_in_dimensional_letters": {
      "type": "boolean",
      "default": true,
      "description": "Show in the Dimensional Letters fab/material picker (Channel Letter Estimator)"
    },
    "show_in_lobby_sign_backer": {
      "type": "boolean",
      "default": true,
      "description": "Show in the Lobby Sign Backer picker"
    },
    "show_in_vinyl_replacement": {
      "type": "boolean",
      "default": false,
      "description": "Show in Sign Maintenance \u2014 Vinyl Replacement action material picker"
    },
    "show_in_replace_returns": {
      "type": "boolean",
      "default": false,
      "description": "Show in Sign Maintenance \u2014 Replace Returns action material picker"
    },
    "show_in_replace_face": {
      "type": "boolean",
      "default": false,
      "description": "Show in Sign Maintenance \u2014 Replace Face action material picker"
    },
    "image_url": {
      "type": "string",
      "description": "Optional image URL for this material."
    }
  },
  "required": [
    "material_name",
    "material_type"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "admin"
      }
    },
    "read": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "update": {
      "user_condition": {
        "role": "admin"
      }
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "DocNumberCounter",
  "type": "object",
  "description": "Singleton counter backing the atomic EST-XXXXX / INV-XXXXX number generator (generateDocNumber function). One record (config_name 'default') holds the next shared sequence number. Estimates and orders draw from the same counter so numbers never overlap.",
  "properties": {
    "config_name": {
      "type": "string",
      "default": "default"
    },
    "next_seq": {
      "type": "number",
      "default": 1,
      "description": "Next sequence number to hand out (shared by EST- and INV- prefixed numbers)."
    }
  },
  "required": [
    "config_name"
  ],
  "rls": {
    "read": {
      "user_condition": {
        "role": "__doc_number_backend_only__"
      }
    },
    "create": {
      "user_condition": {
        "role": "__doc_number_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__doc_number_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__doc_number_backend_only__"
      }
    }
  }
}

{
  "name": "EmailGroup",
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "description": "Name of the email group"
    },
    "description": {
      "type": "string",
      "description": "Description of the email group"
    },
    "permission_sections": {
